const body = $input.first().json.body || $input.first().json || {};
const messageText = (body.messageText || body.message || '').trim();
const senderPhone = body.senderPhone || body.phone || 'Unknown';
const senderName = body.senderName || body.name || 'Valued Patient';
const eventType = body.event || 'whatsapp_message';
const session = body.session || {};

const lower = messageText.toLowerCase();

// 1. Patient Name Extraction
let patientName = session.patientName || senderName;
const nameMatch = messageText.match(/(?:my name is|i am|this is|call me)\s+([a-zA-Z\s]{2,25})/i);
if (nameMatch && nameMatch[1]) {
  patientName = nameMatch[1].trim();
}

// 2. Fee / Pricing Inquiry Detection
const isFeeQuestion = /fee|cost|price|charge|rate|how much|extra/i.test(lower);
const isEmergencyFeeQuestion = isFeeQuestion && /emergency/i.test(lower);

// 3. Real Acute Emergency Detection (Only physical pain/symptoms, NOT questions)
const hasPainOrSymptoms = /severe\s*(?:tooth\s*)?pain|toothache|bleeding|swelling|broken\s*tooth|infection|extreme\s*pain/i.test(lower) || (/emergency|urgent/i.test(lower) && !isFeeQuestion);
const isEmergency = hasPainOrSymptoms && !isFeeQuestion;

// 4. Service Detection
let currentService = session.service || 'General Dental Consultation & Checkup';
if (isEmergency) {
  currentService = 'Emergency Toothache / Acute Dental Care';
} else if (/clean|hygiene|scale/i.test(lower)) {
  currentService = 'Routine Cleaning & Preventative Care';
} else if (/whiten/i.test(lower)) {
  currentService = 'Professional Teeth Whitening';
} else if (/filling|cavity|crown|implant/i.test(lower)) {
  currentService = 'Restorative Dentistry / Filling & Crown';
} else if (/brace|aligner|invisalign/i.test(lower)) {
  currentService = 'Orthodontics & Teeth Alignment';
}

let currentTime = session.preferredTime || '';
let stage = session.stage || 'INIT';
let isBooked = false;
let reply = '';

// Check if user just sent a basic greeting
const isGreetingOnly = /^(hi|hello|hey|salam|assalam|aoa|good morning|good afternoon|good evening)[\s!.]*$/i.test(lower);

if (isEmergency) {
  isBooked = true;
  stage = 'EMERGENCY_CONFIRMED';
  currentTime = 'Today (Immediate Walk-In / Triage)';
  reply = [
    '🚨 *URGENT CARE NOTICE*',
    '',
    `Hi ${patientName}, your case is flagged as *HIGH PRIORITY / EMERGENCY*.`,
    '',
    '📍 *Action Steps:*',
    '• Head directly to our clinic: *123 Healthcare Blvd*',
    '• Our on-duty dentist is being alerted right now',
    '• Emergency walk-in triage is open and ready for you',
    '',
    '📞 If you are on your way, our doors are open!'
  ].join('\n');

} else if (isEmergencyFeeQuestion) {
  isBooked = false;
  reply = [
    '💵 *Emergency Pricing Policy*',
    '',
    '• *No Extra Surcharge:* We do NOT charge extra emergency fees!',
    '• *Standard Triage Fee:* $50 / Rs. 1,500 (covers digital exam & pain-relief assessment)',
    '• *Treatment:* Any required procedure is explained transparently upfront',
    '',
    currentTime ? `🗓️ Your appointment is currently reserved for *${currentTime}*.` : '👉 Are you currently in pain, or would you like to schedule a routine appointment?'
  ].join('\n');

} else if (isFeeQuestion) {
  isBooked = false;
  reply = [
    '💵 *Apex Dental Fees & Pricing*',
    '',
    '• 🦷 *General Exam & Consultation:* $50 / Rs. 1,500',
    '• 🪥 *Routine Cleaning & Scaling:* $80 / Rs. 2,500',
    '• ✨ *Teeth Whitening:* $150 / Rs. 5,000',
    '• 🚨 *Emergency Pain Relief:* Standard $50 fee (No emergency surcharge)',
    '',
    currentTime ? `🗓️ Your appointment is currently reserved for *${currentTime}*.` : '👉 Would morning or afternoon suit you best for a booking?'
  ].join('\n');

} else if (/where|location|address|map|place/i.test(lower)) {
  isBooked = false;
  reply = [
    '📍 *Clinic Location & Hours*',
    '',
    '• *Address:* 123 Healthcare Blvd, Medical District',
    '• *Hours:* Monday – Saturday, 9:00 AM – 6:00 PM',
    '• *Parking:* Free patient parking on-site',
    '',
    currentTime ? `🗓️ We look forward to seeing you at *${currentTime}*!` : '👉 Would morning or afternoon work best for your visit?'
  ].join('\n');

} else {
  let parsedHour = null;
  let isAm = false;
  let isPm = false;

  const timeMatch = lower.match(/(?:at|on|with|time)?\s*(\d{1,2})(?::|\s+)?(\d{2})?\s*(am|pm)?/i);
  if (timeMatch && !/^\d{7,}$/.test(messageText.replace(/\D/g, ''))) {
    const rawH = parseInt(timeMatch[1], 10);
    const ampm = timeMatch[3] ? timeMatch[3].toLowerCase() : '';
    if (rawH >= 1 && rawH <= 12) {
      parsedHour = rawH;
      if (ampm === 'am') isAm = true;
      if (ampm === 'pm') isPm = true;
      if (!ampm) {
        if (rawH >= 8 && rawH <= 11) isAm = true;
        else if (rawH >= 1 && rawH <= 7) isPm = true;
      }
    }
  }

  const isNightOrEarly = isAm && (parsedHour === 12 || (parsedHour >= 1 && parsedHour <= 7));
  const isLateNight = isPm && (parsedHour >= 8 && parsedHour <= 11);

  if (isNightOrEarly || isLateNight || /night|midnight/i.test(lower)) {
    isBooked = false;
    const requestedStr = parsedHour ? `${parsedHour}:00 AM` : 'that hour';
    const recommendedPm = (parsedHour && parsedHour >= 1 && parsedHour <= 6) ? `${parsedHour}:00 PM` : '4:00 PM';
    reply = [
      '⏰ *Clinic Operating Hours*',
      '',
      `Our clinic is open *Monday to Saturday, 9:00 AM – 6:00 PM* (Closed at ${requestedStr}).`,
      '',
      '✨ *Recommended Available Slots:*',
      '• ☀️ Tomorrow Morning: 10:00 AM',
      `• 🌤️ Tomorrow Afternoon: ${recommendedPm}`,
      '',
      `👉 Would *${recommendedPm}* work for you?`
    ].join('\n');
    currentTime = `Pending (Recommended ${recommendedPm})`;
    stage = 'AWAITING_TIME';

  } else if (/change.*(?:morning\s+to\s+afternoon|to\s+afternoon)|switch.*afternoon/i.test(lower) || (lower.includes('afternoon') && lower.includes('change'))) {
    isBooked = false;
    currentTime = 'Tomorrow Afternoon';
    stage = 'AWAITING_TIME';
    reply = [
      '🔄 *Switching to Afternoon*',
      '',
      'We have the following open slots tomorrow:',
      '• 🕐 2:00 PM',
      '• 🕝 3:30 PM',
      '• 🕓 4:00 PM',
      '• 🕔 5:00 PM',
      '',
      '👉 Reply with your preferred time to confirm!'
    ].join('\n');

  } else if (parsedHour) {
    isBooked = true;
    const period = isPm ? 'PM' : 'AM';
    currentTime = `Tomorrow at ${parsedHour}:00 ${period}`;
    stage = 'BOOKED';
    reply = [
      '🎉 *APPOINTMENT CONFIRMED*',
      '',
      `👤 *Patient:* ${patientName}`,
      `🗓️ *Date & Time:* ${currentTime}`,
      `🦷 *Service:* ${currentService}`,
      '👨‍⚕️ *Provider:* Dr. Sarah (Lead Dental Specialist)',
      '📍 *Location:* 123 Healthcare Blvd, Medical District',
      '💵 *Fee:* $50 / Rs. 1,500 (Includes Digital Exam)',
      '',
      '📌 *Quick Reminders:*',
      '• Please arrive 5 minutes before your slot',
      '• Free dedicated parking available on-site',
      '• Need to reschedule? Simply reply here anytime!'
    ].join('\n');

  } else if (lower.includes('afternoon')) {
    isBooked = true;
    currentTime = 'Tomorrow Afternoon (2:30 PM)';
    stage = 'BOOKED';
    reply = [
      '🎉 *APPOINTMENT CONFIRMED*',
      '',
      `👤 *Patient:* ${patientName}`,
      `🗓️ *Date & Time:* ${currentTime}`,
      `🦷 *Service:* ${currentService}`,
      '👨‍⚕️ *Provider:* Dr. Sarah (Lead Dental Specialist)',
      '📍 *Location:* 123 Healthcare Blvd, Medical District',
      '💵 *Fee:* $50 / Rs. 1,500 (Includes Digital Exam)',
      '',
      '📌 *Quick Reminders:*',
      '• Please arrive 5 minutes before your slot',
      '• Free dedicated parking available on-site',
      '• Need to reschedule? Simply reply here anytime!'
    ].join('\n');

  } else if (lower.includes('morning')) {
    isBooked = true;
    currentTime = 'Tomorrow Morning (10:00 AM)';
    stage = 'BOOKED';
    reply = [
      '🎉 *APPOINTMENT CONFIRMED*',
      '',
      `👤 *Patient:* ${patientName}`,
      `🗓️ *Date & Time:* ${currentTime}`,
      `🦷 *Service:* ${currentService}`,
      '👨‍⚕️ *Provider:* Dr. Sarah (Lead Dental Specialist)',
      '📍 *Location:* 123 Healthcare Blvd, Medical District',
      '💵 *Fee:* $50 / Rs. 1,500 (Includes Digital Exam)',
      '',
      '📌 *Quick Reminders:*',
      '• Please arrive 5 minutes before your slot',
      '• Free dedicated parking available on-site',
      '• Need to reschedule? Simply reply here anytime!'
    ].join('\n');

  } else if (isGreetingOnly || stage === 'INIT' || eventType === 'whatsapp_missed_call') {
    isBooked = false;
    stage = 'AWAITING_TIME';
    reply = [
      `👋 *Hi ${patientName}!*`,
      'Welcome to *Apex Dental Clinic*. We noticed we missed your call!',
      '',
      '✨ *How can we help you today?*',
      '• 🚨 *Emergency:* Severe toothache or acute pain',
      '• 🪥 *Routine:* Teeth cleaning, whitening, or checkup',
      '',
      '🗓️ *Available Slots Tomorrow:*',
      '• ☀️ Morning: 9:30 AM | 10:00 AM | 11:30 AM',
      '• 🌤️ Afternoon: 2:00 PM | 3:30 PM | 4:00 PM',
      '',
      '👉 Which time works best for you?'
    ].join('\n');

  } else {
    isBooked = false;
    stage = 'AWAITING_TIME';
    reply = [
      `👋 *Got it, ${patientName}!*`,
      `We can certainly take care of your *${currentService}*.`,
      '',
      '🗓️ *Available Slots Tomorrow:*',
      '• ☀️ Morning: 10:00 AM',
      '• 🌤️ Afternoon: 2:00 PM | 4:00 PM',
      '',
      '👉 Which slot would you prefer?'
    ].join('\n');
  }
}

// 5. Packaging Payload
const triageStatus = isEmergency 
  ? 'HIGH PRIORITY / EMERGENCY (WHATSAPP RECOVERY)' 
  : (isBooked ? 'CONFIRMED BOOKING (WHATSAPP)' : 'INQUIRY / QUALIFYING');

const notes = isEmergency 
  ? `Sub-60s Auto-Recovery: Urgent dental emergency reported: "${messageText.slice(0, 100)}"` 
  : `WhatsApp Booking: Confirmed ${currentService} for ${currentTime || 'Tomorrow'}.`;

const safePhone = String(senderPhone).startsWith('+') ? `'${senderPhone}` : String(senderPhone);

const updatedSession = {
  patientName: patientName,
  senderPhone: senderPhone,
  service: currentService,
  preferredTime: currentTime,
  stage: stage,
  isBooked: isBooked,
  isEmergency: isEmergency,
  lastUpdated: new Date().toISOString()
};

return {
  json: {
    'TIMESTAMP': new Date().toLocaleString(),
    'PATIENT NAME': patientName,
    'PHONE NUMBER': safePhone,
    'SERVICE / REASON': currentService,
    'PREFERRED TIME': currentTime || 'Pending Confirmation',
    'TRIAGE STATUS': triageStatus,
    'NOTES': notes,
    'reply': reply,
    'isBooked': isBooked,
    'isEmergency': isEmergency,
    'updatedSession': updatedSession
  }
};

const item = $input.first().json;
return {
  json: {
    'TIMESTAMP': item['TIMESTAMP'],
    'PATIENT NAME': item['PATIENT NAME'],
    'PHONE NUMBER': item['PHONE NUMBER'],
    'SERVICE / REASON': item['SERVICE / REASON'],
    'PREFERRED TIME': item['PREFERRED TIME'],
    'TRIAGE STATUS': item['TRIAGE STATUS'],
    'NOTES': item['NOTES']
  }
};
